const scenario = $.Trigger.scenario;

const config = {
  pool: {
    backend: 'AAP',
    response: $.Steps.Launch_AAP_Pool_Fault,
    templateId: '21',
    templateName: 'Pool Fault',
    action: 'pool'
  },
  disk: {
    backend: 'AAP',
    response: $.Steps.Launch_AAP_Disk_Fault,
    templateId: '22',
    templateName: 'Disk Fault',
    action: 'disk'
  },
  reset: {
    backend: 'DEMO_CONTROL',
    response: $.Steps.Reset_Demo,
    templateId: '',
    templateName: '',
    action: 'reset'
  },
  autoscale: {
    backend: 'AAP',
    response: $.Steps.Launch_AAP_Autoscale_Fault,
    templateId: '31',
    templateName: 'Start Storefront Capacity Spike',
    action: 'autoscale'
  },
  rollback: {
    backend: 'AAP',
    response: $.Steps.Launch_AAP_Rollback_Fault,
    templateId: '29',
    templateName: 'Deploy Storefront Demo-Bad',
    action: 'rollback'
  }
};

const selected = config[scenario] || {};
const response = selected.response || {};
const body = response.body || {};
const httpStatus = Number(response.status || 0);

let accepted = false;
let jobId = '';
let rawState = '';

if (selected.backend === 'AAP') {
  jobId = body.id !== undefined && body.id !== null ? String(body.id) : '';
  rawState = String(body.status || 'pending');
  accepted = httpStatus === 201 && jobId !== '';
} else if (selected.backend === 'DEMO_CONTROL') {
  jobId = typeof body.job_id === 'string' ? body.job_id : '';
  rawState = String(body.state || '');
  accepted =
    httpStatus === 202 &&
    body.ok === true &&
    body.action === selected.action &&
    body.state === 'accepted' &&
    jobId !== '';
}

$.Helpers.setVariable('execution_backend', selected.backend || 'UNKNOWN');
$.Helpers.setVariable('job_id', jobId);
$.Helpers.setVariable('job_state', accepted ? 'running' : 'launch_failed');
$.Helpers.setVariable('raw_job_state', rawState);
$.Helpers.setVariable('aap_job_template_id', selected.templateId || '');
$.Helpers.setVariable('aap_job_template_name', selected.templateName || '');
$.Helpers.setVariable('job_action', selected.action || '');
$.Helpers.setVariable('launch_http_status', httpStatus);
$.Helpers.setVariable(
  'failure_reason',
  accepted ? '' : 'Execution backend did not return the expected launch response'
);

return {
  accepted,
  backend: selected.backend || 'UNKNOWN',
  http_status: httpStatus,
  job_id: jobId,
  raw_state: rawState
};

const scenario = $.Trigger.scenario;
const config = {
  memory: { backend: 'AAP', response: $.Steps.Launch_AAP_Memory_Fault, action: 'memory', templateId: '33', templateName: 'Inject Memory Pressure' },
  'reset-memory': { backend: 'AAP', response: $.Steps.Launch_AAP_Reset_Memory, action: 'reset-memory', templateId: '35', templateName: 'Restore Memory Baseline' }
};
const selected = config[scenario] || {};
const response = selected.response || {};
const body = response.body || {};
const httpStatus = Number(response.status || 0);
let jobId = '';
let rawState = '';
let accepted = false;
if (selected.backend === 'AAP') {
  jobId = body.id !== undefined && body.id !== null ? String(body.id) : '';
  rawState = String(body.status || 'pending');
  accepted = httpStatus === 201 && jobId !== '';
}
$.Helpers.setVariable('execution_backend', selected.backend || 'UNKNOWN');
$.Helpers.setVariable('job_id', jobId);
$.Helpers.setVariable('job_state', accepted ? 'running' : 'launch_failed');
$.Helpers.setVariable('raw_job_state', rawState);
$.Helpers.setVariable('aap_job_template_id', selected.templateId || '');
$.Helpers.setVariable('aap_job_template_name', selected.templateName || '');
$.Helpers.setVariable('job_action', selected.action || '');
$.Helpers.setVariable('launch_http_status', httpStatus);
$.Helpers.setVariable('failure_reason', accepted ? '' : 'AAP did not return the expected Job Template launch response');
return { accepted, backend: selected.backend || 'UNKNOWN', http_status: httpStatus, job_id: jobId, raw_state: rawState };

const backend = $.Variables.execution_backend;
const expectedJobId = String($.Variables.job_id || '');

let response = {};
let valid = false;
let rawState = '';
let normalizedState = 'unexpected';
let detail = '';

if (backend === 'AAP') {
  response = $.Steps.Get_AAP_Job_Status || {};
  const body = response.body || {};
  const responseJobId =
    body.id !== undefined && body.id !== null ? String(body.id) : '';

  valid = Number(response.status || 0) === 200 && responseJobId === expectedJobId;
  rawState = String(body.status || '');

  if (['pending', 'waiting', 'running'].includes(rawState)) {
    normalizedState = 'running';
  } else if (rawState === 'successful') {
    normalizedState = 'succeeded';
  } else if (['failed', 'error', 'canceled'].includes(rawState)) {
    normalizedState = 'failed';
    detail = 'AAP terminal state: ' + rawState;
  }
} else if (backend === 'DEMO_CONTROL') {
  response = $.Steps.Get_Demo_Job_Status || {};
  const body = response.body || {};
  const responseJobId = String(body.job_id || '');

  valid =
    Number(response.status || 0) === 200 &&
    body.ok === true &&
    responseJobId === expectedJobId;

  rawState = String(body.job_state || '');

  if (['accepted', 'running'].includes(rawState)) {
    normalizedState = 'running';
  } else if (rawState === 'succeeded') {
    normalizedState = 'succeeded';
  } else if (rawState === 'failed') {
    normalizedState = 'failed';
    detail = String(
      (body.job && body.job.error) ||
      body.error ||
      'Demo Control job failed'
    );
  }
}

$.Helpers.setVariable('status_response_valid', valid);
$.Helpers.setVariable('raw_job_state', rawState);
$.Helpers.setVariable('job_state', normalizedState);

if (normalizedState === 'failed' && detail) {
  $.Helpers.setVariable('failure_reason', detail);
}

return {
  valid,
  backend,
  raw_state: rawState,
  normalized_state: normalizedState,
  detail
};

const currentCount = $.Variables.poll_count || 0;
const newCount = currentCount + 1;
$.Helpers.setVariable('poll_count', newCount);
return newCount;
